function syncSkills(){state.evolved=state.skills[0]>=4&&state.skills[2]>=2;state.rain=state.skills[1]>=4&&state.skills[6]>=2;state.thunder=state.skills[3]>=4&&state.skills[7]>=2;$('#skills').innerHTML=state.skills.map((n,i)=>n?'<div>'+(i===0&&state.evolved?'만검귀종':i===1&&state.rain?'만천화우':i===3&&state.thunder?'혈뢰천강':names[i])+'<small>'+n+' 重</small></div>':'').join('')}
