function dash(){if(mode==='play'&&state.dash<=0){Sound.play('dash');state.dash=2.8;state.inv=.45;let v=movement();if(!v.x&&!v.y){v.x=state.facing?.x||1;v.y=state.facing?.y||0}state.p.x+=v.x*160;state.p.y+=v.y*160;state.effects.push({x:state.p.x,y:state.p.y,r:45,t:.4,max:.4,color:'#d4edbe'})}}$('#dash').addEventListener('pointerdown',e=>{e.preventDefault();dash()});
addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault();if(e.key===' '&&!e.repeat)dash();if(e.key==='Escape')pause()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);addEventListener('blur',()=>{keys={};pointer=null;if(mode==='play')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='play')pause()});
