function movement(){let x=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),y=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(pointer){x=Math.abs(pointer.dx)>5?pointer.dx/42:0;y=Math.abs(pointer.dy)>5?pointer.dy/42:0}let l=Math.hypot(x,y);return l>0?{x:x/Math.max(1,l),y:y/Math.max(1,l)}:{x:0,y:0}}
function upgrade(){$('#again').hidden=true;Sound.play('level');mode='upgrade';pointer=null;$('#modal').hidden=false;$('#modalEyebrow').textContent='내공 돌파 · 경지 '+state.level;$('#modalTitle').textContent='새로운 무공을 깨우치세요';$('#resume').hidden=true;$('#retry').hidden=true;let pool=names.map((_,i)=>i).filter(i=>state.skills[i]<5);for(let j=pool.length-1;j>0;j--){let k=Math.floor(Math.random()*(j+1));[pool[j],pool[k]]=[pool[k],pool[j]]}let options=pool.slice(0,3);if(!options.length){state.p.hp=Math.min(state.p.max,state.p.hp+30);mode='play';$('#modal').hidden=true;showNotice('운기조식 · 체력 +30');return}$('#choices').innerHTML='';for(let i of options){let b=document.createElement('button');b.title=['검기 4 + 호신검 2 → 만검귀종','비도 4 + 독무 2 → 만천화우','검기 4 + 호신검 2 → 만검귀종','진각 4 + 천뢰장 2 → 혈뢰천강','','','비도 4 + 독무 2 → 만천화우','진각 4 + 천뢰장 2 → 혈뢰천강'][i];b.innerHTML='<span style="font-size:28px">'+['⚔','✦','✧','◎','☯','➶','毒','ϟ'][i]+'</span><strong>'+names[i]+' '+(state.skills[i]+1)+'重</strong><small>'+desc[i]+'</small><small class="recipe">'+b.title+'</small>';b.onclick=()=>{state.skills[i]++;if(typeof Sound!=='undefined')Sound.play('level');if(i===4){state.p.max+=25;state.p.hp=Math.min(state.p.max,state.p.hp+45)}syncSkills();$('#modal').hidden=true;mode='play'};$('#choices').append(b)}}
