function spawn(boss=false){const s=state,p=s.p;const edge=Math.floor(Math.random()*4),margin=24;let x=p.x,y=p.y;if(edge<2){x+=(Math.random()-.5)*W;y+=(edge?1:-1)*(H/2+margin)}else{x+=(edge===2?-1:1)*(W/2+margin);y+=(Math.random()-.5)*H}const f=factions[selected].enemy[Math.random()<.5?0:1],elite=!boss&&s.time>=60&&Math.random()<.1;const hp=(boss?650:18+s.time*.13)*(elite?3:1)*stages[stageId].difficulty;s.enemies.push({x,y,f,hp,max:hp,speed:(boss?43:43+Math.random()*16+s.time*.045)*(elite?1.15:1),boss,elite,hit:0,fire:1.5+Math.random()*2,charge:0,name:boss?factions[f].name+' 장로':elite?['청룡검수','추혼살수','혈의호법'][f]:['정파 검수','사파 낭인','마교 교도'][f]})}

function damage(e,n,direction){if(e.dead)return;n*=(1+Profile.data.training.power*.05)*(selected===2?1.12:1);e.hp-=n;hitFeedback(e,n,direction);if(n>=10&&state.texts.length<35)state.texts.push({x:e.x,y:e.y-22,t:.65,n:Math.round(n)});if(e.hp<=0&&!e.dead){e.dead=true;deathFeedback(e);state.kills++;state.gems.push({x:e.x,y:e.y,value:e.boss?25:e.elite?6:2});if(Math.random()<.035)state.drops.push({x:e.x,y:e.y,type:Math.random()<.6?'heal':'magnet'});if(e.final)state.bossDead=true}}
function update(dt){let s=state,p=s.p,v=movement();if(v.x||v.y)s.facing=v;s.time+=dt;let wave=Math.floor(s.time/60);if(wave>s.wave){s.wave=wave;for(let i=0;i<12;i++)if(s.enemies.length<280)spawn();showNotice(['','추격대가 합류합니다','정예 무인 출현','포위망이 좁혀집니다','장로 출현 · 제한 시간 안에 처치'][Math.min(4,wave)])}s.shake=Math.max(0,(s.shake||0)-dt);s.hitFlash=Math.max(0,(s.hitFlash||0)-dt);s.dash-=dt;s.inv-=dt;p.x+=v.x*(165+s.skills[5]*16+(selected===1?12:0))*dt;p.y+=v.y*(165+s.skills[5]*16+(selected===1?12:0))*dt;s.spawn-=dt;if(s.spawn<=0){for(let i=0;i<3+Math.floor(s.time/55);i++)if(s.enemies.length<280)spawn();s.spawn=Math.max(.22,.42-s.time/1600)}if(s.time>=110&&!s.miniboss){s.miniboss=true;summonBoss(false)}if(s.time>=240&&!s.boss){s.boss=true;summonBoss(true)}if(s.time>=300){end(!s.boss||!!s.bossDead);return}
updateFeedback(s,dt);runAttacks(s,dt);
for(let e of s.enemies){if(e.dead)continue;updateEnemy(e,s,dt);
e.hit-=dt;if(Math.hypot(e.x-p.x,e.y-p.y)<(e.boss?28:16)&&s.inv<=0){p.hp-=e.boss?25:9;s.shake=.18;s.hitFlash=.15;Sound.play('hurt');s.inv=.7;if(p.hp<=0){end(false);return}}if(s.skills[2])for(let j=0;j<Math.min(6,s.skills[2]+1);j++){let a=s.ring*2.5+j*Math.PI*2/(Math.min(6,s.skills[2]+1));if(Math.hypot(e.x-p.x-Math.cos(a)*65,e.y-p.y-Math.sin(a)*65)<23)damage(e,dt*(35+s.skills[2]*15))}}
buildEnemyGrid(s);for(let b of s.shots){let oldX=b.x,oldY=b.y;b.x+=b.vx*dt;b.y+=b.vy*dt;b.t-=dt;for(let e of shotTargets(s,oldX,oldY,b.x,b.y))if(!e.dead&&!b.hit.has(e)&&segmentDistance(e.x,e.y,oldX,oldY,b.x,b.y)<(e.boss?30:20)){damage(e,b.damage,Math.atan2(b.vy,b.vx));b.hit.add(e)}}s.shots=s.shots.filter(b=>b.t>0);
for(let b of s.hostile){let oldX=b.x,oldY=b.y;b.x+=b.vx*dt;b.y+=b.vy*dt;b.t-=dt;if(s.inv<=0&&segmentDistance(p.x,p.y,oldX,oldY,b.x,b.y)<15){p.hp-=8;s.shake=.18;s.hitFlash=.15;Sound.play('hurt');s.inv=.55;b.t=0;if(p.hp<=0){end(false);return}}}s.hostile=s.hostile.filter(b=>b.t>0);
for(let t of s.texts){t.t-=dt;t.y-=dt*25}s.texts=s.texts.filter(t=>t.t>0);
for(let d of s.drops)if(Math.hypot(d.x-p.x,d.y-p.y)<24){d.dead=true;if(d.type==='heal'){p.hp=Math.min(p.max,p.hp+30);showNotice('금창약 · 체력 +30')}else{for(let g of s.gems){g.x=p.x+(Math.random()-.5)*20;g.y=p.y+(Math.random()-.5)*20}showNotice('흡성대법 · 내공 회수')}}s.drops=s.drops.filter(d=>!d.dead);
s.enemies=s.enemies.filter(e=>!e.dead&&(e.boss||Math.hypot(e.x-p.x,e.y-p.y)<Math.max(W,H)*1.6));for(let g of s.gems){let d=Math.hypot(g.x-p.x,g.y-p.y);if(d<100+Profile.data.training.fortune*10){g.x+=(p.x-g.x)*dt*7;g.y+=(p.y-g.y)*dt*7}if(d<15){s.xp+=g.value;g.dead=true;Sound.play('pickup')}}s.gems=s.gems.filter(g=>!g.dead);if(s.gems.length>450){let g=s.gems.shift();let near=s.gems.reduce((a,b)=>Math.hypot(a.x-g.x,a.y-g.y)<Math.hypot(b.x-g.x,b.y-g.y)?a:b);near.value+=g.value}if(s.drops.length>35)s.drops.shift();for(let e of s.effects)e.t-=dt;s.effects=s.effects.filter(e=>e.t>0);if(s.xp>=s.need){s.xp-=s.need;s.level++;s.need=5+s.level*3;upgrade()}updateHUD(s,dt)}
function format(t){return String(Math.floor(t/60)).padStart(2,'0')+':'+String(Math.floor(t%60)).padStart(2,'0')}
